links=[('새 실행 파일','EngineMigrator-runtime-component-preview-20261023/EngineMigrator.App.exe'),('배포 ZIP','EngineMigrator-runtime-component-preview-20261023.zip'),('HTML 가이드','../docs/guide.html'),('전체 검증 근거','runtime-component-tests/milestone-verification.json'),('실제 왕복 데이터','runtime-component-roundtrip-v7/PROJECT-82bd0ee94218/project-roundtrip-verification.json'),('복원 프로젝트 대응표','runtime-component-roundtrip-v7/PROJECT-82bd0ee94218/resource-port.html'),('이전 빈 객체 검증','development-report-runtime-creation-20261023.html')]
